1	//! The run record: what every operation a vc-x1 run commits says
2	//! about the run that made it.
3	//!
4	//! A run is one vc-x1 invocation. Its record is written as operation
5	//! attributes, jj's string-to-string map, the one jj-cli keeps its
6	//! own `args` in, so `jj op log` shows it with no template of ours.
7	//! This module is the typed side of that map: the keys are
8	//! [`RunAttribute`], the id a [`RunId`], so the strings are made and
9	//! read in one place. Every session the process opens shares the
10	//! run, so a `-s b` run stamps both repos with one id.
11	
12	use std::collections::BTreeMap;
13	use std::fmt;
14	use std::str::FromStr;
15	use std::sync::OnceLock;
16	use std::time::{SystemTime, UNIX_EPOCH};
17	
18	use jj_lib::transaction::Transaction;
19	
20	/// The run record's format, written with every record, so a later
21	/// vc-x1 reading an older operation knows what it is reading.
22	pub const RUN_FORMAT: u32 = 1;
23	
24	/// The keys of the run record in an operation's attributes.
25	#[derive(Clone, Copy, Debug, PartialEq, Eq)]
26	pub enum RunAttribute {
27	    /// The run's [`RunId`].
28	    Id,
29	    /// The run's subcommand, as clap names it: `commit`, `squash-push`.
30	    Command,
31	    /// The run's command line, each argument a shell word, for people.
32	    Args,
33	    /// The record's format, [`RUN_FORMAT`].
34	    Format,
35	}
36	
37	impl RunAttribute {
38	    /// The attribute's key, as the op store keeps it.
39	    pub fn key(self) -> &'static str {
40	        match self {
41	            Self::Id => "vc-x1-run",
42	            Self::Command => "vc-x1-command",
43	            Self::Args => "vc-x1-args",
44	            Self::Format => "vc-x1-run-format",
45	        }
46	    }
47	}
48	
49	/// A run's id: 128 bits in the UUID v7 layout, 48 bits of Unix
50	/// milliseconds, the version 7, 12 random bits, the variant `0b10`,
51	/// and 62 random bits. So ids sort by when their runs began, and
52	/// stay unique beyond the one op log they are written in. Written as
53	/// 32 lowercase hex digits.
54	#[derive(Clone, Copy, Debug, PartialEq, Eq, PartialOrd, Ord, Hash)]
55	pub struct RunId(pub u128);
56	
57	impl RunId {
58	    /// A new id for a run beginning now.
59	    pub fn now() -> Self {
60	        let ms = SystemTime::now()
61	            .duration_since(UNIX_EPOCH)
62	            .map(|d| d.as_millis())
63	            .unwrap_or(0); // OK: a clock before 1970 sorts first, its random bits keep it unique
64	        Self::from_parts(ms, rand::random::<u128>())
65	    }
66	
67	    /// The id for a run begun at `ms` Unix milliseconds, its random
68	    /// fields taken from `random`.
69	    fn from_parts(ms: u128, random: u128) -> Self {
70	        let timestamp = (ms & 0xffff_ffff_ffff) << 80;
71	        let version = 0x7 << 76;
72	        let rand_a = ((random >> 64) & 0xfff) << 64;
73	        let variant = 0b10 << 62;
74	        let rand_b = random & ((1 << 62) - 1);
75	        Self(timestamp | version | rand_a | variant | rand_b)
76	    }
77	}
78	
79	impl fmt::Display for RunId {
80	    /// 32 lowercase hex digits.
81	    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
82	        write!(f, "{:032x}", self.0)
83	    }
84	}
85	
86	impl FromStr for RunId {
87	    type Err = String;
88	
89	    /// Exactly 32 hex digits, so a value that is not ours never reads
90	    /// as a run.
91	    fn from_str(s: &str) -> Result<Self, Self::Err> {
92	        if s.len() != 32 || !s.bytes().all(|b| b.is_ascii_hexdigit()) {
93	            return Err(format!("not a run id, 32 hex digits: {s:?}"));
94	        }
95	        u128::from_str_radix(s, 16)
96	            .map(Self)
97	            .map_err(|e| format!("not a run id: {s:?}: {e}"))
98	    }
99	}
100	
101	/// One run's record, made once per process.
102	#[derive(Debug)]
103	pub struct Run {
104	    /// The run's id.
105	    pub id: RunId,
106	    /// The subcommand, as clap names it.
107	    pub command: String,
108	    /// The command line, each argument a shell word.
109	    pub args: String,
110	}
111	
112	impl Run {
113	    /// A run of `command` beginning now, its command line this
114	    /// process's, the body left out.
115	    fn new(command: &str) -> Self {
116	        let args: Vec<String> = std::env::args_os()
117	            .map(|arg| arg.to_string_lossy().into_owned())
118	            .collect();
119	        Run {
120	            id: RunId::now(),
121	            command: command.to_string(),
122	            args: recorded_args(&args),
123	        }
124	    }
125	
126	    /// The record as the op store keeps it, key and value.
127	    fn attributes(&self) -> [(RunAttribute, String); 4] {
128	        [
129	            (RunAttribute::Id, self.id.to_string()),
130	            (RunAttribute::Command, self.command.clone()),
131	            (RunAttribute::Args, self.args.clone()),
132	            (RunAttribute::Format, RUN_FORMAT.to_string()),
133	        ]
134	    }
135	}
136	
137	/// A run record as read back from an operation's attributes: the
138	/// reading side of [`Run`].
139	#[derive(Clone, Debug, PartialEq, Eq)]
140	pub struct RunTag {
141	    /// The run's id.
142	    pub id: RunId,
143	    /// The subcommand, `?` when the record has none.
144	    pub command: String,
145	    /// The command line as recorded, empty when the record has none.
146	    pub args: String,
147	}
148	
149	impl RunTag {
150	    /// The run record in `attributes`, `None` when they hold no id
151	    /// that parses, an operation no vc-x1 run of this format made.
152	    pub fn from_attributes(attributes: &BTreeMap<String, String>) -> Option<Self> {
153	        let get = |a: RunAttribute| attributes.get(a.key());
154	        let id = get(RunAttribute::Id)?.parse().ok()?;
155	        Some(RunTag {
156	            id,
157	            command: get(RunAttribute::Command)
158	                .cloned()
159	                .unwrap_or_else(|| "?".into()), // OK: a record without its command still names its run
160	            args: get(RunAttribute::Args).cloned().unwrap_or_default(), // OK: a record without its command line still names its run
161	        })
162	    }
163	}
164	
165	static RUN: OnceLock<Run> = OnceLock::new();
166	
167	/// Begin this process's run as `command`, the subcommand clap parsed,
168	/// before any session commits an operation. Called once, by `main`.
169	pub fn begin_run(command: &str) {
170	    RUN.get_or_init(|| Run::new(command));
171	}
172	
173	/// This process's run: the one `begin_run` made, or where nothing
174	/// began one, a test, one made on first use with the command `?`.
175	pub fn run() -> &'static Run {
176	    RUN.get_or_init(|| Run::new("?"))
177	}
178	
179	/// Stamp `tx` with this process's run, so the operation it commits
180	/// says which vc-x1 run made it. Every transaction a session starts
181	/// takes it: `RepoSession::start_tx` and the three the snapshot cycle
182	/// starts on its own.
183	pub fn tag_run(tx: &mut Transaction) {
184	    for (attribute, value) in run().attributes() {
185	        tx.set_attribute(attribute.key().to_string(), value);
186	    }
187	}
188	
189	/// The flag the record leaves out whole, flag and value: a commit's
190	/// body, which the commit carries and which would otherwise repeat on
191	/// every operation of the run. A `--title` is kept with its text, one
192	/// line that names the run.
193	const DROPPED_FLAG: &str = "--body";
194	
195	/// A value longer than this, in characters, or holding a newline, is
196	/// kept as its length whatever flag it follows, so free text another
197	/// flag carries stays out. Long enough to keep a deep path.
198	const LONG_VALUE: usize = 100;
199	
200	/// The command line as the record keeps it: each argument a shell
201	/// word, [`DROPPED_FLAG`] and its value left out, in the `=` form
202	/// too, and any other value over [`LONG_VALUE`] or with a newline as
203	/// its length.
204	fn recorded_args(args: &[String]) -> String {
205	    let mut words = Vec::new();
206	    let mut drop_next = false;
207	    for arg in args {
208	        if std::mem::take(&mut drop_next) {
209	            continue;
210	        }
211	        if arg == DROPPED_FLAG {
212	            drop_next = true;
213	        } else if arg
214	            .split_once('=')
215	            .is_some_and(|(flag, _)| flag == DROPPED_FLAG)
216	        {
217	            // Dropped with its value.
218	        } else if arg.contains('\n') || arg.chars().count() > LONG_VALUE {
219	            words.push(format!("<{} chars>", arg.chars().count()));
220	        } else {
221	            words.push(shell_word(arg));
222	        }
223	    }
224	    words.join(" ")
225	}
226	
227	/// A recorded command line as it is shown: split back into its words
228	/// and kept by [`recorded_args`]'s rules, so a record written before
229	/// a rule shows as one written after it.
230	pub fn shown_args(recorded: &str) -> String {
231	    recorded_args(&split_words(recorded))
232	}
233	
234	/// The words of a line [`shell_word`] made: split at spaces outside
235	/// quotes, a single-quoted stretch taken as it is, and a backslash
236	/// outside quotes taking the next character as it is.
237	fn split_words(line: &str) -> Vec<String> {
238	    let mut words = Vec::new();
239	    let mut word = String::new();
240	    let mut in_word = false;
241	    let mut quoted = false;
242	    let mut chars = line.chars();
243	    while let Some(c) = chars.next() {
244	        match (quoted, c) {
245	            (true, '\'') => quoted = false,
246	            (true, c) => word.push(c),
247	            (false, ' ') => {
248	                if std::mem::take(&mut in_word) {
249	                    words.push(std::mem::take(&mut word));
250	                }
251	                continue;
252	            }
253	            (false, '\'') => quoted = true,
254	            (false, '\\') => word.extend(chars.next()),
255	            (false, c) => word.push(c),
256	        }
257	        in_word = true;
258	    }
259	    if in_word {
260	        words.push(word);
261	    }
262	    words
263	}
264	
265	/// `arg` as a shell word: bare when plain, single-quoted otherwise.
266	fn shell_word(arg: &str) -> String {
267	    let plain = !arg.is_empty()
268	        && arg
269	            .chars()
270	            .all(|c| c.is_ascii_alphanumeric() || "-_./=:@,+%".contains(c));
271	    if plain {
272	        arg.to_string()
273	    } else {
274	        format!("'{}'", arg.replace('\'', r"'\''"))
275	    }
276	}
